contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: perform an initial deposit (possibly zero) then a subsequent deposit of amt.
    // Assert that when the second deposit has positive value, the recorded balance strictly increases.
    function runTest(uint256 initialAmt, uint256 amt) public payable {
        // Ensure this test contract has enough ETH to forward
        require(address(this).balance >= initialAmt + amt, "insufficient balance");

        // Make an initial deposit (could be zero)
        c.deposit{value: initialAmt}();

        // Read balance after initial deposit via public mapping getter: balances is public in original? It's not public in C,
        // so we cannot access it directly. Instead observe address(c).balance and then perform second deposit and
        // observe that address(c).balance increases by exactly amt and that sender's withdrawability reflects it.
        // To keep to allowed observables, we will use address(c).balance before and after and ensure that when amt>0,
        // the contract's balance increases strictly. This captures that zero deposits were not allowed to revert on P
        // but the mutant allows zero and the differing revert behavior is captured by requiring amt>0 and testing.

        uint256 before = address(c).balance;

        // perform the decisive deposit
        c.deposit{value: amt}();

        uint256 after = address(c).balance;

        // If a positive amount was sent, the contract balance must strictly increase by that amount.
        // This holds for the original (which reverts on overflow but not on zero-value revert semantics),
        // but the mutant's changed revert/allowance of zero-value deposits will break tests that rely on
        // distinguishing zero acceptance; here we assert the strict increase when amt>0.
        assert(amt == 0 || after == before + amt);
    }

    // Allow the contract to receive ETH so tests can fund it
    receive() external payable {}
}

