pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the depositor address and the amount (amount may be zero)
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero to be a valid EOA in fuzz space
        vm.assume(actor != address(0));
        // bound amount to a reasonable range but allow zero
        amount = bound(amount, 0, 1 ether);

        // fund the actor so they can send `amount` wei
        vm.deal(actor, amount);

        bool ok;
        // perform deposit as actor and catch reverts; reference accepts amount==0, mutant reverts for amount==0
        vm.prank(actor);
        try c.deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for the reference contract, deposits with amount == 0 do NOT revert (ok == true);
        // the mutant replaces assert with require and will revert when amount == 0, so the single assertion
        // checks that either the call succeeded, or amount > 0 (i.e., only zero-value deposit may be rejected by mutant).
        // We assert the universal property the reference satisfies: calls with amount == 0 must NOT revert.
        if (amount == 0) {
            assertTrue(ok);
        } else {
            // for amount > 0 both should accept when funded; assert that call succeeded
            assertTrue(ok);
        }
    }
}

