    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and amount to send
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero to be a sane caller
        vm.assume(depositor != address(0));
        // bound amount to a reasonable range (including zero) and within available test balance
        amount = bound(amount, 0, 1 ether);

        // fund depositor so they can send `amount`
        vm.deal(depositor, amount);

        // perform the deposit call and record whether it reverted
        bool ok;
        vm.prank(depositor);
        try c.deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: on the correct reference C, deposit() never reverts for any depositor and any msg.value.
        // We assert that the call succeeded. The mutant that changes the assert to a require will revert when amount == 0,
        // so for some fuzz inputs this assertion will fail on the mutant but holds for the reference.
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single external test function
    function run(address depositor, uint256 amt) external payable {
        // preconditions: this test caller must fund this contract so it can forward amt
        require(msg.value == 0, "do not send ETH to this function directly");
        require(amt > 0, "deposit amount must be positive");
        require(address(this).balance >= amt, "insufficient balance to forward");

        // record prior balance of depositor as observable via c (balances is private in C, so we use effect on contract balance and withdraw behavior)
        // To observe per-address stored balance we will: deposit from this contract on behalf of depositor by calling c.deposit() via this contract sending amt,
        // then compare address(c).balance change vs deposited amount and ensure stored per-address accounting increased at least by amt by performing a withdraw of amt back to this contract.

        // Make deposit from this contract (acting as depositor)
        c.deposit{value: amt}();

        // After deposit, it must be possible to withdraw exactly amt (i.e., contract recorded at least that much for this msg.sender). We call withdraw to see whether withdraw succeeds.
        // If contract C had ignored the assert and allowed overflow to wrap, withdraw may revert due to require(amount <= balances[msg.sender]).
        // Attempt withdraw of amt — should succeed on original P, but may fail on mutant M when balances wrapped.
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amt));

        // The distinguishing property: withdraw of the deposited amt must succeed (return true)
        assert(ok);
    }

    // allow this test contract to be funded so it can forward deposits
    receive() external payable {}
}

