contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address depositor, uint256 amount) public payable {
        // we will send `amount` wei with the deposit call; ensure this contract has it
        require(address(this).balance >= amount && amount > 0);

        bool reverted;
        // call deposit sending Ether
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: if the call returned (did not revert) then the contract's balance must have increased by amount
        // We observe address(c).balance only and the revert flag. This captures that original rejects deposits that would not increase recorded balances (i.e., would overflow), while mutant accepts them.
        uint256 bal = address(c).balance;
        // We cannot observe prior balance after the call except by reasoning: if reverted==false then bal must be >= amount
        // To make a general test expressible only with params and reverted, we assert that if the call did not revert then the target contract's balance is at least amount (i.e., it received the funds).
        assert(reverted || bal >= amount);
    }
    receive() external payable { }
}

